//! The wire forms of finding M-2, pinned against AUTOSCRIPT.JS'S OWN recorded
//! rules — not against agreement between two Rust files. Every literal below
//! is copied from `autoscript.js` (afirma-ui-miniapplet-deploy, the same clone
//! every other test in this crate quotes) with its line, and each test drives
//! it through openfirma's real parsing or dispatch:
//!
//! - session ids: VALID_CHARS_TO_ID, line 1902; generated by
//!   `generateRandomString`, checked character class AND length cap.
//! - the echo contract, line 2608: `echo=-<idsession>@EOF` — a launch's probe
//!   answer that must round-trip through our endpoint exactly.
//! - the error parser, lines 2651-2659: an answer is only "an error" when it
//!   starts with the right prefix AND `" - "` sits at index 8; anything else
//!   reaches the page as raw text (a signature treated as prose). So every
//!   openfirma refusal must survive that exact predicate.
//! - the success path's fold, lines 2889-2899: '-'→'+' then '_'→'/' before
//!   base64 — pinned in fake_sede.rs; here the same fold is asserted on a real
//!   signature made by dispatch itself (with the page-side reader re-implemented
//!   from the recorded source, not imported).
//!
//! The file also pins WireError's whole table against AutoFirma's catalogues
//! (the numbers are constants; their SAF_xx partners are the recorded
//! `OLD_ERRORS_ASSOCIATION`, quoted in each entry's doc-comment).

use openfirma_browser::dispatch::{WireError, WireTarget, wire_target};
use openfirma_browser::uri;

/// Recorded (autoscript.js:1902):
/// `var VALID_CHARS_TO_ID = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";`
const VALID_CHARS_TO_ID: &str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

fn check_id(id: &str) -> bool {
    // The recorded generation rule (`generateRandomString`) plus the parser's
    // length cap (UrlParametersToSign: at most 20, because it becomes a file
    // name on the intermediate server).
    !id.is_empty() && id.len() <= 20 && id.chars().all(|c| VALID_CHARS_TO_ID.contains(c))
}

#[test]
fn recorded_session_ids_parse_and_rejects_are_the_page_s_own() {
    // The page never sends a session id outside that class; openfirma must
    // not invent one either. drive both directions through the REAL parser.
    for id in ["abc123", "aZ3tRy9XkLmNpQwErTyU"] {
        assert!(check_id(id), "{id} is a valid generated id");
        let uri = format!("afirma://selectcert?idsession={id}&ver=4.1");
        let parsed = uri::parse(&uri).unwrap_or_else(|e| panic!("{id}: {e}"));
        // A-5: the value keeps its original case (the parser only lowercases
        // for the CHECK, like UrlParametersToSign's own checkIdSession).
        assert_eq!(parsed.id_session.as_deref(), Some(id));
    }
    // A 21-character id is over the cap — AutoFirma refuses it, and so does
    // the parser, with INVALID_SESSION_ID (620010) on the wire.
    let long = "a".repeat(21);
    let err = uri::parse(&format!("afirma://selectcert?idsession={long}")).unwrap_err();
    assert_eq!(err.wire_error().af_code, "620010");
    // A hyphen is outside VALID_CHARS_TO_ID: the page cannot generate one and
    // a probe cannot arrive with one; accepting it would be guessing.
    let err = uri::parse("afirma://selectcert?idsession=ab-cd").unwrap_err();
    assert_eq!(err.wire_error().af_code, "620010");
}

#[test]
fn uppercase_session_ids_are_accepted_and_kept_verbatim() {
    // A-5: UrlParametersToSign lowercases only for the membership test; the
    // stored value (and what a follow-up getresult must match) keeps its case.
    let parsed = uri::parse("afirma://selectcert?idsession=AbC123").unwrap();
    assert_eq!(parsed.id_session.as_deref(), Some("AbC123"));
}

#[test]
fn the_echo_contract_answers_the_pages_own_string() {
    // Recorded (autoscript.js:2608):
    //   var echoString = "echo=-" + sessionId + "@EOF";
    // The answer rule (recorded from WebSocketProtocolOperation's echo branch
    // and pinned in fake_sede.rs already): the endpoint answers `OK`. Here we
    // pin the URI-level fact openfirma depends on: an echo message parses as
    // NO operation — it must never be mistaken for a signing call whose result
    // is bytes. (`serve.rs`'s echo branch is pinned end-to-end in fake_sede;
    // this test pins the parser boundary.)
    let msg = format!("echo=-{}@EOF", "abc123");
    let err = uri::parse(&msg).unwrap_err();
    // Refused as not-an-afirma-scheme call — the socket-parameters code, which
    // is AutoFirma's own answer for a message that cannot name an operation.
    assert_eq!(err.wire_error().af_code, "620016");
}

/// The recorded error predicate — autoscript.js lines 2642-2659 verbatim:
///
/// ```js
/// if (data.length > 7 && data.substring(0, 4).toLowerCase() == "err-" && data.indexOf(":=") != -1) {
///     ...
///     // Se espera el formato "err-XX:= CODIGO - MENSAJE", donde CODIGO tiene exactamente 8 caracteres
///     var errorCodeAndMessage = data.substring(data.indexOf(":=") + 2);
///     if (errorCodeAndMessage.indexOf(" - ") != 8) {
///         errorMessage = errorCodeAndMessage;               // NOT a code: prose
///     } else {
///         errorCode = errorCodeAndMessage.substring(0, 8);   // "AF" + 6 digits
///         errorMessage = errorCodeAndMessage.substring(11);
///     }
/// ```
///
/// So `" - "` sits at index **8 of the body after `:=`** — eight characters in:
/// `AFxxxxxx` exactly. A refusal that fails this predicate surfaces to the page
/// as prose where a code was expected; openfirma's must never.
fn autofirma_sees_an_error(text: &str) -> Option<&'static str> {
    if !(text.len() > 7 && text[..4].eq_ignore_ascii_case("err-")) {
        return None;
    }
    let sep = text.find(":=")?;
    let body = &text[sep + 2..];
    if body.find(" - ") != Some(8) {
        return None;
    }
    let candidate = &body[..8];
    if !candidate.starts_with("AF") || !candidate[2..].bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    WireError::ALL
        .iter()
        .find(|w| *candidate == format!("AF{}", w.af_code))
        .map(|w| w.af_code)
}

#[test]
fn every_openfirma_refusal_survives_the_pages_error_parser() {
    // The whole catalogue, both wire forms: for 4.1+ the recorded predicate
    // above must find an error with a known AF code; below 4.1 the text starts
    // with its SAF_xx (or is CANCEL), which is what the legacy readers split on.
    for wire in WireError::ALL {
        let modern = wire.wire_new();
        assert_eq!(
            autofirma_sees_an_error(&modern),
            Some(wire.af_code),
            "the page cannot read {modern:?} back as an error"
        );
        let legacy = wire.wire_old();
        if wire.af_code == "500001" {
            assert_eq!(legacy, "CANCEL");
        } else {
            assert!(
                legacy.starts_with(&format!("{}: ", wire.old_code)),
                "legacy form of {}: {legacy:?}",
                wire.af_code
            );
        }
    }
}

#[test]
fn the_cancellation_forms_match_the_recorded_branches() {
    // getErrorMessage: only CANCELLED_OPERATION gets err-11:= (recorded);
    // everything else is err-00:=. The old protocol answers a cancellation
    // with the bare literal and nothing else.
    assert!(
        WireError::CANCELLED
            .wire_new()
            .starts_with("err-11:=AF500001")
    );
    for wire in WireError::ALL {
        if wire.af_code != "500001" {
            assert!(
                wire.wire_new().starts_with("err-00:=AF"),
                "{}",
                wire.af_code
            );
        }
    }
}

#[test]
fn wire_target_follows_the_recorded_4_1_boundary() {
    // ProtocolInvocationLauncherErrorManager: `hasSupportTo(4.1)` alone selects
    // the modern form (recorded constant PROTOCOL_VERSION_WITH_ERROR_CODES).
    assert_eq!(wire_target(Some("4.1")), WireTarget::Protocol41Plus);
    assert_eq!(wire_target(Some("5")), WireTarget::Protocol41Plus);
    assert_eq!(wire_target(Some("4")), WireTarget::Legacy);
    assert_eq!(wire_target(Some("3.9")), WireTarget::Legacy);
    // A broken version string is AutoFirma's VERSION_0 fallback: a client that
    // NAMED a version and named it wrong lives down there.
    assert_eq!(wire_target(Some("cuatro")), WireTarget::Legacy);
    // No version at all is openfirma's documented deviation (see wire_target's
    // doc-comment): the form every autoscript-1.10+ client reads.
    assert_eq!(wire_target(None), WireTarget::Protocol41Plus);
}

#[test]
fn a_dispatch_refusal_carries_its_own_wire_text_end_to_end() {
    // An unsupported format is the most common refusal a misconfigured page
    // meets; dispatch's error must arrive with AutoFirma's 600105/SAF_06 pair,
    // and the modern text must pass the page's predicate.
    let err = match openfirma_browser::dispatch::protocol_request_for(
        "CAdES-ASiC-S",
        openfirma_core::alg::DigestAlg::Sha256,
    ) {
        Ok(_) => panic!("ASiC-S is refused by name"),
        Err(e) => e,
    };
    assert_eq!(err.wire.af_code, "600105");
    assert_eq!(err.wire.old_code, "SAF_06");
    let text = err.wire(WireTarget::Protocol41Plus);
    assert_eq!(autofirma_sees_an_error(&text), Some("600105"));
    // and the legacy form for a pre-4.1 caller names SAF_06, whose message is
    // the ERRORS table's own ("Formato de firma no soportado").
    let old = err.wire(WireTarget::Legacy);
    assert!(
        old.starts_with("SAF_06: Formato de firma no soportado"),
        "{old}"
    );
}
